# Load required libraries
library(readr)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)

# Helper functions for missing value mapping
standard_missing_code <- function(x) {
  if (is.na(x)) return(NA_real_)
  if (x >= 0) return(x)
  # Map specific negative codes
  if (x == -9) return(-9)
  if (x == -8) return(-8)
  if (x == -7) return(-7)
  if (x == -6 || x == -5 || x == -4) return(-8)
  if (x == -3) return(-3)
  if (x == -2) return(-2)
  if (x == -1) return(-1)
  # Default fallback
  return(-8)
}

# Collapse to major NS-SEC categories (major 1-7). Minor categories become NA.
major_nssec_map <- function(x) {
  if (is.na(x)) return(NA_real_)
  if (x < 0) return(x)  # keep negative missing codes
  # Map detailed categories to major categories 1-7
  if (x %in% 1:7) return(x)
  # For categories with decimal part like 3.1, 3.2 etc.
  # Extract integer part
  int_part <- floor(x)
  if (int_part %in% 1:7) return(int_part)
  # Otherwise set as NA (minor categories)
  return(NA_real_)
}

# Transform NS-SEC variable: handle missing codes then collapse to major
transform_nssec <- function(x) {
  if (is.na(x)) return(NA_real_)
  if (x < 0) return(standard_missing_code(x))
  return(major_nssec_map(x))
}

# Function to read a tab-delimited file with read_delim
read_tab <- function(file) {
  read_delim(file.path("data/input", file), delim = "\t", col_types = cols(), trim_ws = TRUE, progress = FALSE)
}

# List of files from metadata
files <- c(
  "wave_one_lsype_young_person_2020.tab",
  "wave_four_lsype_young_person_2020.tab",
  "wave_five_lsype_young_person_2020.tab",
  "wave_six_lsype_young_person_2020.tab",
  "wave_seven_lsype_young_person_2020.tab",
  "wave_eight_lsype_young_person_2020.tab",
  "ns9_2022_main_interview.tab"
)

# Read all files into a list
data_list <- map(files, ~ read_tab(.x))
names(data_list) <- files

# Merge all datasets by full_join on NSID
merged_df <- reduce(data_list, full_join, by = "NSID")

# Derive NS-SEC variables for each wave
merged_df <- merged_df %>% mutate(
  nssec17 = transform_nssec(as.numeric(W4nsseccatYP)),
  nssec18 = transform_nssec(as.numeric(W5nsseccatYP)),
  nssec19 = transform_nssec(as.numeric(w6nsseccatYP)),
  nssec20 = transform_nssec(as.numeric(W7NSSECCat)),
  nssec25 = transform_nssec(as.numeric(W8DNSSEC17)),
  nssec32 = transform_nssec(as.numeric(W9NSSEC))
)

# Select only ID and derived NS-SEC variables
final_df <- merged_df %>% select(NSID, nssec17, nssec18, nssec19, nssec20, nssec25, nssec32)

# Write to CSV
write_csv(final_df, "data/output/cleaned_data.csv")

