library(readr)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)

# Missing value mapping utilities
standard_missing_code <- function(x) {
  if (is.na(x)) return(NA_real_)
  if (x >= 0) return(x)
  switch(as.character(x),
         "-9" = -9,
         "-8" = -8,
         "-7" = -7,
         "-6" = -8,
         "-5" = -8,
         "-4" = -8,
         "-3" = -3,
         "-2" = -2,
         "-1" = -1,
         "-999" = -9,
         "-998" = -9,
         "-997" = -9,
         "-995" = -9,
         "-94"  = -8,
         "-92"  = -9,
         "-91"  = -1,
         "-99"  = -3,
         "-100" = -9,
         "-97"  = -9,
         -8)
}

# Map detailed NS-SEC to major categories 1-7
major_nssec_map <- function(x) {
  if (is.na(x)) return(NA_real_)
  if (x < 0) return(x)
  if (x %in% 1:7) return(x)
  int_part <- floor(x)
  if (int_part %in% 1:7) return(int_part)
  return(NA_real_)
}

transform_nssec <- function(x) {
  if (is.null(x)) return(NULL)
  vapply(x, function(v){
    if (is.na(v)) return(NA_real_)
    if (v < 0) return(standard_missing_code(v))
    return(major_nssec_map(v))
  }, FUN.VALUE = numeric(1))
}

read_tab <- function(file) {
  path <- file.path("data/input", file)
  if (!file.exists(path) || file.info(path)$size == 0) {
    message("File missing or empty: ", path)
    return(NULL)
  }
  read_delim(path, delim = "\t", col_types = cols(), trim_ws = TRUE, progress = FALSE)
}

# File list
files <- c(
  "wave_one_lsype_young_person_2020.tab",
  "wave_four_lsype_young_person_2020.tab",
  "wave_five_lsype_young_person_2020.tab",
  "wave_six_lsype_young_person_2020.tab",
  "wave_seven_lsype_young_person_2020.tab",
  "ns8_2015_derived.tab",
  "ns9_2022_main_interview.tab"
)

# Read data frames that contain NSID
list_df <- list()
for (f in files) {
  df <- read_tab(f)
  if (!is.null(df) && "NSID" %in% names(df)) {
    list_df[[f]] <- df
  }
}

# Merge by NSID
merged_df <- reduce(list_df, full_join, by = "NSID")

# Derive nssec variables, checking column existence
