library(dplyr)
library(tidyr)
library(purrr)
library(labelled)

# Helper functions for missing value mapping
standard_missing_code <- function(x) {
  if (is.na(x)) return(NA_real_)
  if (x >= 0) return(x)
  # Map specific negative codes
  if (x == -9) return(-9)
  if (x == -8) return(-8)
  if (x == -7) return(-7)
  if (x == -6 || x == -5 || x == -4) return(-8)
  if (x == -3) return(-3)
  if (x == -2) return(-2)
  if (x == -1) return(-1)
  # Default fallback
  return(-8)
}

# Collapse to major NS-SEC categories (major 1-7). Minor categories become NA.
major_nssec_map <- function(x) {
  if (is.na(x)) return(NA_real_)
  if (x < 0) return(x)  # keep negative missing codes
  # Map detailed categories to major categories 1-7
  if (x %in% 1:7) return(x)
  # For categories with decimal part like 3.1, 3.2 etc.
  # Extract integer part
  int_part <- floor(x)
  if (int_part %in% 1:7) return(int_part)
  # Otherwise set as NA (minor categories)
  return(NA_real_)
}

# Transform NS-SEC variable: handle missing codes then collapse to major
transform_nssec <- function(x) {
  if (is.na(x)) return(NA_real_)
  if (x < 0) return(standard_missing_code(x))
  return(major_nssec_map(x))
}

# Function to read a tab-delimited file with read_delim
