  if (is.na(x)) return(NA_real_)
  if (x >= 0) return(x)
  # Map specific negative codes
  if (x == -9) return(-9)
  if (x == -8) return(-8)
  if (x == -7) return(-7)
  if (x == -6 || x == -5 || x == -4) return(-8)
  if (x == -3) return(-3)
  if (x == -2) return(-2)
  if (x == -1) return(-1)
  # Default fallback
