  # Map detailed categories to major categories 1-7
  if (x %in% 1:7) return(x)
  # For categories with decimal part like 3.1, 3.2 etc.
  # Extract integer part
  int_part <- floor(x)
  if (int_part %in% 1:7) return(int_part)
  # Otherwise set as NA (minor categories)
  return(NA_real_)
}

